  const HEIGHT = canvas.height;

  // Ship definition
  const ship = {
    x: WIDTH / 2,
    y: HEIGHT * 0.8,
    w: 30,
    h: 20,
    speed: 4,
    color: '#0f0',
    draw() {

  draw() {
    ctx.fillStyle = this.color;
    ctx.beginPath();
    ctx.moveTo(this.x, this.y);
    ctx.lineTo(this.x - this.w / 2, this.y + this.h);
    ctx.lineTo(this.x + this.w / 2, this.y + this.h);
    ctx.closePath();
    ctx.fill();
  }
};

